const SCENES=['01','02','03','04','05'];
export const DATABASE='diez-alma-notas-v1';export const MAX_LENGTH=2000;
function checked(text){if(typeof text!=='string'||!text.trim())throw new Error('Escribe algo antes de guardar.');if(text.length>MAX_LENGTH)throw new Error('La nota admite hasta 2000 caracteres. Tu texto sigue en el editor.');return text;}
function open(){return new Promise((resolve,reject)=>{if(!globalThis.indexedDB){reject(new Error('Este navegador no permite abrir las notas locales. Tu texto sigue en el editor.'));return;}let req;try{req=indexedDB.open(DATABASE,1);}catch{reject(new Error('No se pudo abrir el almacenamiento local. Tu texto sigue en el editor.'));return;}req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('notes'))req.result.createObjectStore('notes',{keyPath:'id'});};req.onerror=()=>reject(new Error('No se pudo abrir el almacenamiento local. Tu texto sigue en el editor.'));req.onblocked=()=>reject(new Error('Cierra otras pestañas de esta versión e inténtalo de nuevo.'));req.onsuccess=()=>{const db=req.result;db.onversionchange=()=>db.close();resolve(db);};});}
async function transaction(mode,fn){const db=await open();return new Promise((resolve,reject)=>{let value;const tx=db.transaction('notes',mode);let error;const failed=()=>reject(error||new Error('No se pudo guardar el cambio. Tu texto sigue en el editor. Comprueba el espacio o los permisos del navegador.'));try{fn(tx.objectStore('notes'),v=>value=v,msg=>{error=new Error(msg);tx.abort();});}catch{tx.abort();}tx.oncomplete=()=>{db.close();resolve(value);};tx.onerror=()=>{db.close();failed();};tx.onabort=()=>{db.close();failed();};});}
export const list=()=>transaction('readonly',(store,set)=>{const r=store.getAll();r.onsuccess=()=>set(r.result.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)));});
export const create=(text,scene)=>{const value=checked(text);if(!SCENES.includes(scene))throw new Error('Elige un escenario para la nota.');const now=new Date().toISOString();const note={id:crypto.randomUUID(),world:'alma',scene,text:value,createdAt:now,updatedAt:now};return transaction('readwrite',(store,set)=>{store.add(note);set(note);});};
export const update=(id,text)=>{const value=checked(text);return transaction('readwrite',(store,set,abort)=>{const r=store.get(id);r.onsuccess=()=>{if(!r.result){abort('Esta nota ya no está guardada. Tu texto sigue en el editor.');return;}const note={...r.result,text:value,updatedAt:new Date().toISOString()};store.put(note);set(note);};});};
export const remove=id=>transaction('readwrite',store=>store.delete(id));
